const http = this.helpers.httpRequest;
const resp = await http({ method:'GET', url:'https://open.er-api.com/v6/latest/USD' });
const rates = resp.rates;
const cop = rates.COP;
if (!cop) return [];

const trm = cop.toLocaleString('es-CO', {minimumFractionDigits:2, maximumFractionDigits:2});
const usdPorCop = (1/cop).toFixed(6);
const fecha = resp.time_last_update_utc?.split(' ')?.[0] || new Date().toISOString().split('T')[0];

const text = `💵 *TRM — ${fecha}*\n\n💰 *$${trm} COP* por 1 USD\n💱 1 COP = ${usdPorCop} USD\n🇪🇺 1 USD = ${rates.EUR?.toFixed(2)}\n\n📊 *Tasas LATAM:*\n🇲🇽 MXN: ${rates.MXN?.toFixed(2)}\n🇧🇷 BRL: ${rates.BRL?.toFixed(2)}\n🇵🇪 PEN: ${rates.PEN?.toFixed(2)}\n🇨🇱 CLP: ${rates.CLP?.toFixed(0)}\n\n⚡ *TRM Alertas*`;

await http({
  method:'POST',
  url:'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
  headers:{ 'apikey':'wasapea-evo-key-2026', 'Content-Type':'application/json' },
  body:{ number:'573106055920', text }
});

return { sent: true, trm: cop };
